mapper.select:
SELECT
    oi.ORDER_NUM, oi.CLI_CODE, oi.ORDER_ID, oi.STATUS, oi.ORDER_DATE,
    it.ITEM_NUM, it.PRODUCT, it.PRODUCT_LABEL, it.WIDTH, it.LENGTH,
    it.ROLLS, it.DESTINATION, it.NOTE, it.DELIVERY_DATE, it.UNIT_PRICE, it.ALIAS_NAME
FROM ORDER_INFO oi
LEFT JOIN ORDER_ITEM it ON it.ORDER_NUM = oi.ORDER_NUM
WHERE oi.CLI_CODE = #{cliCode}
AND oi.ORDER_DATE >= #{from}
AND oi.ORDER_DATE < #{to}
ORDER BY oi.ORDER_DATE DESC, oi.ORDER_NUM DESC, it.ITEM_NUM ASC
